function BusinessModule({active}:{active:string}){const items=businessModules[active]||[`Manage ${active.toLowerCase()} for this business only`,'All records are ownership-checked by the backend'];return <div className="module-workspace vendor-module"><span><Settings/></span><small>PRIVATE VENDOR PORTAL</small><h3>{active}</h3><p>This workspace is restricted to the selected business, assigned branches and the signed-in employee’s role.</p><ul>{items.map(item=><li key={item}><Check/>{item}</li>)}</ul><div className="module-status"><i></i> Business ownership, branch assignment and staff permission enforced by the backend</div></div>}

