function CustomerModule({active}:{active:string}){const module=customerModules[active]||{description:`Manage ${active.toLowerCase()} from your customer account.`,items:['Your information remains private','Only authorized marketplace records appear here']};const Icon=module.icon||ShoppingBag;return <div className="customer-module"><span><Icon/></span><h3>{active}</h3><p>{module.description}</p><ul>{module.items.map(item=><li key={item}><Check size={14}/>{item}</li>)}</ul>{module.href&&<a className="dashboard-primary" href={module.href}>{module.action}<ChevronRight/></a>}<div className="module-status"><i></i> Connected to the secure customer workflow</div></div>}

function BusinessAdvertisementManager({session,business,ads,products,refresh}:{session:Session;business?:ManagedBusiness;ads:Ad[];products:Product[];refresh:()=>void}){const[saving,setSaving]=useState(false);const[message,setMessage]=useState('');async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!business)return;const formEl=event.currentTarget;const form=new FormData(formEl);setSaving(true);setMessage('');try{await api.createAd(session.accessToken,business.id,String(form.get('productId')),String(form.get('title')));formEl.reset();setMessage('Advertisement submitted for review.');refresh();}catch(error){setMessage(error instanceof Error?error.message:'Advertisement could not be submitted.')}finally{setSaving(false)}}return <div className="dashboard-content"><div className="dashboard-welcome"><div><span>PUBLIC CAMPAIGNS</span><h2>Advertisement management</h2><p>Create and submit advertisements owned by {business?.name||'this business'}.</p></div></div><form className="management-form" onSubmit={submit}><label>Advertisement title<input name="title" minLength={2} required/></label><label>Product<select name="productId" required><option value="">Select a product</option>{products.map(product=><option value={product.id} key={product.id}>{product.name}</option>)}</select></label><button className="dashboard-primary" disabled={saving||!business||!products.length}>{saving?'Submitting…':'Submit for approval'}</button>{message&&<div className="customer-feedback wide">{message}</div>}</form><section className="dashboard-card responsive-table"><header><div><h3>Your advertisements</h3><p>Only campaigns owned by this business are shown</p></div></header><div className="business-table-head"><b>Title</b><b>Product</b><b>Ends</b><b>Visibility</b></div>{ads.map(ad=><div className="business-table-row" key={ad.id}><span>{ad.title}</span><span>{ad.product?.name||'Product campaign'}</span><span>{ad.endsAt?new Date(ad.endsAt).toLocaleDateString():'No end date'}</span><span>Public when approved</span></div>)}{!ads.length&&<EmptyMini text="No approved advertisements yet"/>}</section></div>}
function BusinessOrders({session,business,orders,refresh}:{session:Session;business?:ManagedBusiness;orders:Order[];refresh:()=>void}){const[filter,setFilter]=useState('ALL');const[updating,setUpdating]=useState('');const[message,setMessage]=useState('');const statuses=['ALL','PENDING','CONFIRMED','PAID','PROCESSING','SHIPPED','DELIVERED','CANCELLED','REFUNDED'];const visible=filter==='ALL'?orders:orders.filter(order=>order.status===filter);const next:Record<string,{label:string,status:string}[]>={PENDING:[{label:'Confirm',status:'CONFIRMED'},{label:'Cancel',status:'CANCELLED'}],CONFIRMED:[{label:'Prepare',status:'PROCESSING'},{label:'Cancel',status:'CANCELLED'}],PAID:[{label:'Prepare',status:'PROCESSING'},{label:'Refund',status:'REFUNDED'}],PROCESSING:[{label:'Dispatch',status:'SHIPPED'},{label:'Cancel',status:'CANCELLED'}],SHIPPED:[{label:'Complete',status:'DELIVERED'}]};async function transition(orderId:string,status:string){if(!business)return;setUpdating(orderId);setMessage('');try{await api.updateBusinessOrderStatus(session.accessToken,business.id,orderId,status);setMessage(`Order updated to ${status.toLowerCase()}.`);refresh();}catch(error){setMessage(error instanceof Error?error.message:'Order status could not be updated.')}finally{setUpdating('')}}return <div className="dashboard-content"><div className="dashboard-welcome"><div><span>PRIVATE FULFILMENT</span><h2>Business orders</h2><p>Only orders belonging to this business are available here.</p></div></div>{message&&<div className="customer-feedback">{message}</div>}<div className="order-filters">{statuses.map(status=><button className={filter===status?'active':''} onClick={()=>setFilter(status)} key={status}>{status.replaceAll('_',' ')}</button>)}</div><section className="dashboard-card responsive-table"><div className="business-table-head orders"><b>Order</b><b>Customer</b><b>Products</b><b>Amount</b><b>Payment</b><b>Delivery</b><b>Status / date</b><b>Actions</b></div>{visible.map((order:any)=><div className="business-table-row orders" key={order.id}><span>#{order.id.slice(0,8)}</span><span>Customer<small>Fulfilment details protected</small></span><span>{order.items.map((item:any)=>`${item.quantity}× ${item.productName}`).join(', ')}</span><span>{order.currency} {Number(order.total).toFixed(2)}</span><span>{order.payments?.[0]?.status||'PENDING'}</span><span>Not assigned</span><span>{order.status}<small>{new Date(order.createdAt).toLocaleDateString()}</small></span><span>{(next[order.status]||[]).map(action=><button disabled={updating===order.id} onClick={()=>transition(order.id,action.status)} key={action.status}>{updating===order.id?'Updating…':action.label}</button>)}</span></div>)}{!visible.length&&<EmptyMini text="No orders in this status"/>}</section></div>}
function BusinessInventory({business,products}:{business?:ManagedBusiness;products:Product[]}){return <div className="dashboard-content"><div className="dashboard-welcome"><div><span>PRIVATE STOCK CONTROL</span><h2>Inventory</h2><p>Stock, supplier and movement information is visible only to authorized staff.</p></div><button className="dashboard-primary">+ Add stock</button></div><section className="dashboard-card responsive-table"><div className="business-table-head inventory"><b>Product</b><b>Branch</b><b>Available</b><b>Reserved</b><b>Reorder</b><b>Supplier</b><b>Last restock</b><b>Status</b><b>Actions</b></div>{products.map(product=><div className="business-table-row inventory" key={product.id}><span>{product.name}</span><span>{business?.branches?.[0]?.name||'All branches'}</span><span>{product.stockQuantity||0}</span><span>0</span><span>5</span><span>Not assigned</span><span>{product.updatedAt?new Date(product.updatedAt).toLocaleDateString():'—'}</span><span>{(product.stockQuantity||0)===0?'OUT OF STOCK':(product.stockQuantity||0)<=5?'LOW STOCK':'AVAILABLE'}</span><span><button>Add</button><button>Adjust</button><button>Transfer</button><button>Damage</button><button>Alert</button><button>History</button></span></div>)}{!products.length&&<EmptyMini text="No inventory records"/>}</section></div>}

function BusinessAdminPanel({session,business,refresh}:{session:Session;business?:ManagedBusiness;refresh:()=>void}){
  const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [selectedBranches,setSelectedBranches]=useState<string[]>([]);
  const currentRole=business?.members.find(member=>member.userId===session.user.id)?.role;const canManage=currentRole==='OWNER';
  const roles=[['MANAGER','Manager'],['SALES','Sales'],['INVENTORY','Inventory'],['MARKETING','Marketing'],['FINANCE','Finance'],['SUPPORT','Customer support'],['DELIVERY','Delivery']] as const;
  async function addStaff(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!business)return;const formEl=event.currentTarget;const data=new FormData(formEl);setBusy(true);setMessage('');try{await api.addBusinessStaff(session.accessToken,business.id,{phone:String(data.get('phone')),role:String(data.get('role')),branchIds:selectedBranches});setMessage('Staff member added successfully. Their permissions are active immediately.');formEl.reset();setSelectedBranches([]);await refresh();}catch(error){setMessage(error instanceof Error?error.message:'Staff member could not be added.')}finally{setBusy(false)}}
  return <div className="dashboard-content admin-panel"><div className="dashboard-welcome"><div><span>STAFF &amp; PERMISSIONS</span><h2>Team access</h2><p>{canManage?'Manage your team, roles and branch access':`View team roles and branch access`} for {business?.name||'this store'}.</p></div><span className="admin-role"><ShieldCheck/> Signed in as {currentRole?.toLowerCase()||'staff'}</span></div><section className="admin-panel-grid"><form className="dashboard-card staff-form" onSubmit={addStaff}><header><div><h3>{canManage?'Add staff member':'Read-only access'}</h3><p>{canManage?'The person must first have a registered ZimMarket account.':'Only the business owner can add staff or change permissions.'}</p></div><Users/></header>{canManage?<><label>Staff phone number<input name="phone" type="tel" placeholder="+263 77 123 4567" required/></label><label>Role<select name="role" defaultValue="SALES">{roles.map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label><fieldset><legend>Branch access</legend>{business?.branches.length?<div className="branch-options">{business.branches.map(branch=><label key={branch.id}><input type="checkbox" checked={selectedBranches.includes(branch.id)} onChange={event=>setSelectedBranches(current=>event.target.checked?[...current,branch.id]:current.filter(id=>id!==branch.id))}/><span>{branch.name}<small>{branch.city}</small></span></label>)}</div>:<p className="staff-hint">No branches have been created yet. The employee will receive business-level access for their role.</p>}</fieldset><button className="dashboard-primary" disabled={busy}>{busy?<><LoaderCircle className="spin"/>Adding staff…</>:<><Plus/>Add staff member</>}</button></>:<div className="permission-warning"><Eye/><div><b>View only</b><p>You can see the team and its permissions, but only the business owner can make changes.</p></div></div>}{message&&<div className="customer-feedback">{message}</div>}</form><section className="dashboard-card staff-list"><header><div><h3>Store team</h3><p>{business?.members.length||0} active member{business?.members.length===1?'':'s'}</p></div><span>{business?.members.length||0}</span></header><div className="staff-records">{business?.members.map(member=><article key={member.id}><span className="staff-avatar">{(member.user?.fullName||member.user?.phone||'S').slice(0,2).toUpperCase()}</span><div><b>{member.user?.fullName||'Store team member'}</b><small>{member.user?.phone||'Account details protected'}{member.user?.email?` · ${member.user.email}`:''}</small><div>{member.branches?.length?member.branches.map(item=><i key={item.branchId}>{item.branch?.name||'Branch'}</i>):<i>All business / unassigned</i>}</div></div><strong>{member.role.replaceAll('_',' ')}</strong></article>)}</div></section></section><section className="dashboard-card role-guide"><header><div><h3>Roles and permissions</h3><p>{canManage?'Give each employee only the access needed for their job.':'Permission definitions are shown for reference only.'}</p></div></header><div>{roles.map(([value,label])=><article key={value}><ShieldCheck/><span><b>{label}</b><small>{value==='MANAGER'?'View staff and manage daily store operations':value==='FINANCE'?'Payments, earnings, payouts and reports':value==='INVENTORY'?'Products, stock, suppliers and purchase orders':value==='MARKETING'?'Storefront, promotions and advertisements':value==='SUPPORT'?'Customers, messages, returns and support':value==='DELIVERY'?'Orders, dispatch and deliveries':'Orders, quotations, customers and point of sale'}</small></span></article>)}</div></section></div>;
}

function BranchManager({session,business,refresh}:{session:Session;business?:ManagedBusiness;refresh:()=>void}) {
  const [open,setOpen]=useState(false);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!business)return;const data=new FormData(event.currentTarget);setBusy(true);setMessage('');try{await api.createBranch(session.accessToken,business.id,{name:String(data.get('name')),province:String(data.get('province')),city:String(data.get('city')),suburb:String(data.get('suburb')||''),deliveryAreas:String(data.get('deliveryAreas')||'').split(',').map(item=>item.trim()).filter(Boolean),operatingHours:{summary:String(data.get('operatingHours')||'')}});setMessage('Branch added successfully.');setOpen(false);await refresh();}catch(error){setMessage(error instanceof Error?error.message:'Branch could not be added.')}finally{setBusy(false)}}
  return <div className="dashboard-content"><div className="dashboard-welcome"><div><span>STORE LOCATIONS</span><h2>Branches</h2><p>Add physical locations, operating hours and delivery areas.</p></div><button className="dashboard-primary" onClick={()=>setOpen(value=>!value)}>{open?'Cancel':'+ Add branch'}</button></div>{open&&<form className="management-form branch-form" onSubmit={submit}><label>Branch name<input name="name" required minLength={2}/></label><label>Province<input name="province" required/></label><label>City<input name="city" required/></label><label>Suburb<input name="suburb"/></label><label className="wide">Operating hours<input name="operatingHours" placeholder="Mon–Fri 08:00–17:00, Sat 08:00–13:00"/></label><label className="wide">Delivery areas<input name="deliveryAreas" placeholder="Harare CBD, Avondale, Borrowdale"/><small>Separate areas with commas.</small></label><button className="dashboard-primary" disabled={busy}>{busy?'Saving…':'Save branch'}</button></form>}{message&&<div className="customer-feedback">{message}</div>}<section className="branch-card-grid">{business?.branches.map(branch=><article className="dashboard-card branch-card" key={branch.id}><span><Building2/></span><div><h3>{branch.name}</h3><p>{[branch.suburb,branch.city,branch.province].filter(Boolean).join(', ')}</p><small>{branch.deliveryAreas?.length?`Delivers to ${branch.deliveryAreas.join(', ')}`:'Delivery areas not configured'}</small><b>{branch.operatingHours?'Operating hours configured':'Operating hours required'}</b></div></article>)}{!business?.branches.length&&<section className="dashboard-card dashboard-empty"><Building2/><h3>No branches yet</h3><p>Add your first store location to continue onboarding.</p></section>}</section></div>;
}

function ServiceManager({session,business,services,refresh}:{session:Session;business?:ManagedBusiness;services:MarketplaceService[];refresh:()=>void}) {
  const [open,setOpen]=useState(false);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!business)return;const data=new FormData(event.currentTarget);setBusy(true);setMessage('');try{await api.createBusinessService(session.accessToken,business.id,{name:String(data.get('name')),category:String(data.get('category')),description:String(data.get('description')||''),durationMinutes:Number(data.get('durationMinutes')),price:data.get('price')?Number(data.get('price')):undefined,currency:'USD'});setMessage('Service published successfully.');setOpen(false);await refresh();}catch(error){setMessage(error instanceof Error?error.message:'Service could not be created.')}finally{setBusy(false)}}
  return <div className="dashboard-content"><div className="dashboard-welcome"><div><span>SERVICE CATALOGUE</span><h2>Services</h2><p>Create services customers can discover and book.</p></div><button className="dashboard-primary" onClick={()=>setOpen(value=>!value)}>{open?'Cancel':'+ Add service'}</button></div>{open&&<form className="management-form" onSubmit={submit}><label>Service name<input name="name" required/></label><label>Category<input name="category" required/></label><label>Duration in minutes<input name="durationMinutes" type="number" min="5" defaultValue="30" required/></label><label>Price (USD)<input name="price" type="number" min="0" step="0.01"/></label><label className="wide">Description<textarea name="description" rows={3}/></label><button className="dashboard-primary" disabled={busy}>{busy?'Publishing…':'Publish service'}</button></form>}{message&&<div className="customer-feedback">{message}</div>}<section className="dashboard-card product-management"><header><div><h3>Service catalogue</h3><p>{services.length} active service{services.length===1?'':'s'}</p></div></header>{services.map(service=><div className="data-row" key={service.id}><span className="record-icon"><CalendarDays/></span><div><b>{service.name}</b><small>{service.category} · {service.durationMinutes} minutes</small></div><span className="status-badge">ACTIVE</span><strong>{service.price==null?'Quote':`${service.currency||'USD'} ${Number(service.price).toFixed(2)}`}</strong></div>)}{!services.length&&<EmptyMini text="No services yet"/>}</section></div>;
}

function BusinessStorefront({business,data}:{business?:ManagedBusiness;data:DashboardData}) {
  const settings=(business?.settings||{}) as Partial<VendorSettings>;const published=business?.status==='ACTIVE';
  return <div className="dashboard-content"><div className="dashboard-welcome"><div><span>PUBLIC STORE</span><h2>My storefront</h2><p>Preview the information customers see on your public store page.</p></div>{published?<a className="dashboard-primary" href={`/shops/${business?.slug}`}>View live storefront</a>:<span className="admin-role"><ShieldCheck/> Awaiting platform approval</span>}</div><section className="dashboard-card storefront-preview"><div className="storefront-banner" style={settings.banner?{backgroundImage:`url(${settings.banner})`}:undefined}></div><div className="storefront-profile">{settings.logo?<img src={String(settings.logo)} alt="Store logo"/>:<span><Store/></span>}<div><small>{business?.verificationLevel||'UNVERIFIED'}</small><h2>{settings.storeName||business?.name}</h2><p>{settings.description||'Complete your business profile to add a public description.'}</p><b>{settings.openingHours||'Operating hours not configured'}</b></div></div><div className="storefront-summary"><span><strong>{data.products.length}</strong> Products</span><span><strong>{data.services.length}</strong> Services</span><span><strong>{business?.branches.length||0}</strong> Branches</span><span><strong>{data.ads.length}</strong> Advertisements</span></div></section></div>;
}

type VendorSettings={storeName:string;description:string;publicPhone:string;publicEmail:string;logo:string;banner:string;openingHours:string;deliveryAreas:string;collectionEnabled:boolean;paymentMethods:string[];returnPolicy:string;currency:string;taxNumber:string;orderNotifications:boolean;lowStockNotifications:boolean;twoFactorEnabled:boolean;profileComplete:boolean;mediaComplete:boolean;hoursComplete:boolean;deliveryComplete:boolean;paymentsComplete:boolean};
const defaultVendorSettings:VendorSettings={storeName:'',description:'',publicPhone:'',publicEmail:'',logo:'',banner:'',openingHours:'',deliveryAreas:'',collectionEnabled:true,paymentMethods:[],returnPolicy:'',currency:'USD',taxNumber:'',orderNotifications:true,lowStockNotifications:true,twoFactorEnabled:false,profileComplete:false,mediaComplete:false,hoursComplete:false,deliveryComplete:false,paymentsComplete:false};

function BusinessNotifications({session,business}:{session:Session;business?:ManagedBusiness}){const[feed,setFeed]=useState<{messages:any[];orderAlerts:any[];stockAlerts:any[]}>({messages:[],orderAlerts:[],stockAlerts:[]});const[loading,setLoading]=useState(true);const[error,setError]=useState('');async function load(){if(!business)return;setLoading(true);try{setFeed(await api.businessNotifications(session.accessToken,business.id));setError('')}catch(reason){setError(reason instanceof Error?reason.message:'Notifications could not be loaded.')}finally{setLoading(false)}}useEffect(()=>{load()},[business]);async function read(id:string){if(!business)return;await api.readBusinessNotification(session.accessToken,business.id,id);setFeed(current=>({...current,messages:current.messages.map(item=>item.id===id?{...item,readAt:new Date().toISOString()}:item)}))}const unread=feed.messages.filter(item=>!item.readAt).length+feed.orderAlerts.filter(item=>['PENDING','CONFIRMED'].includes(item.status)).length+feed.stockAlerts.length;return <div className="dashboard-content"><div className="dashboard-welcome"><div><span>LIVE BUSINESS ALERTS</span><h2>Notifications</h2><p>{unread} item{unread===1?'':'s'} need attention across orders, stock and provider messages.</p></div><button className="dashboard-primary" onClick={load}>Refresh</button></div>{error&&<div className="dashboard-error"><AlertTriangle/>{error}</div>}{loading?<div className="dashboard-loader inline"><LoaderCircle className="spin"/></div>:<section className="dashboard-card notification-feed"><header><div><h3>Latest activity</h3><p>Private alerts for {business?.name}</p></div></header>{feed.orderAlerts.map(order=><div className="notification-row unread" key={`order-${order.id}`}><ShoppingBag/><div><b>Order #{order.id.slice(0,8)} · {order.status}</b><small>{order.currency} {Number(order.total).toFixed(2)} · {new Date(order.createdAt).toLocaleString()}</small></div><a href="#" onClick={event=>event.preventDefault()}>View order</a></div>)}{feed.stockAlerts.map(product=><div className="notification-row unread" key={`stock-${product.id}`}><Boxes/><div><b>Low stock: {product.name}</b><small>{product.stockQuantity} remaining · updated {new Date(product.updatedAt).toLocaleString()}</small></div><span>Inventory</span></div>)}{feed.messages.map(item=><div className={`notification-row ${item.readAt?'':'unread'}`} key={item.id}><Bell/><div><b>{String(item.template).replaceAll('-',' ')}</b><small>{item.channel} · {new Date(item.createdAt).toLocaleString()}</small></div>{item.readAt?<span>Read</span>:<button onClick={()=>read(item.id)}>Mark read</button>}</div>)}{!feed.messages.length&&!feed.orderAlerts.length&&!feed.stockAlerts.length&&<EmptyMini text="No business notifications yet"/>}</section>}</div>}

function BusinessSettings({session,business,data,refresh}:{session:Session;business?:ManagedBusiness;data:DashboardData;refresh:()=>void}){
  const key=`zimmarket.vendor-settings.${business?.id||'default'}`;const[tab,setTab]=useState('Business profile');const[message,setMessage]=useState('');const[savingSettings,setSavingSettings]=useState(false);const[settings,setSettings]=useState<VendorSettings>({...defaultVendorSettings,storeName:business?.name||''});
  useEffect(()=>{const destinations:Record<number,string>={2:'Branches',3:'Products',7:'Staff & Permissions',8:'My Storefront',9:'Advertisements'};const buttons=[...document.querySelectorAll<HTMLButtonElement>('.settings-steps button')];const cleanups=Object.entries(destinations).map(([index,target])=>{const button=buttons[Number(index)];const open=()=>navigateDashboard(target);button?.addEventListener('click',open);return()=>button?.removeEventListener('click',open)});return()=>cleanups.forEach(cleanup=>cleanup())},[]);
  useEffect(()=>{if(!business)return;api.businessSettings(session.accessToken,business.id).then(result=>setSettings(current=>({...current,...(result.settings||{}),storeName:String((result.settings||{}).storeName||business.name)}))).catch(error=>setMessage(error instanceof Error?error.message:'Settings could not be loaded from the backend.'))},[business,session.accessToken]);
  function update<K extends keyof VendorSettings>(field:K,value:VendorSettings[K]){setSettings(current=>({...current,[field]:value}));setMessage('')}
  async function save(event:FormEvent){event.preventDefault();if(!business)return;const next={...settings,profileComplete:Boolean(settings.storeName&&settings.description&&settings.publicPhone),mediaComplete:Boolean(settings.logo&&settings.banner),hoursComplete:Boolean(settings.openingHours),deliveryComplete:Boolean(settings.deliveryAreas||settings.collectionEnabled),paymentsComplete:Boolean(settings.paymentMethods.length)};setSavingSettings(true);setMessage('');try{const result=await api.updateBusinessSettings(session.accessToken,business.id,next);setSettings({...next,...result.settings} as VendorSettings);setMessage('Business settings saved to the secure backend.');await refresh();}catch(error){setMessage(error instanceof Error?error.message:'Settings could not be saved.')}finally{setSavingSettings(false)}}
  const steps=[['Create store profile',settings.profileComplete,'Business profile'],['Upload logo and banner',settings.mediaComplete,'Storefront'],['Add branches',Boolean(business?.branches?.length),'Branches'],['Add products or services',Boolean(data.products.length||data.services.length),'Products'],['Configure operating hours',settings.hoursComplete,'Storefront'],['Configure delivery and collection',settings.deliveryComplete,'Delivery'],['Configure payment methods',settings.paymentsComplete,'Payments'],['Add staff',Boolean(business?.members?.length&&business.members.length>1),'Staff & Permissions'],['Publish storefront',business?.status==='ACTIVE','My Storefront'],['Create first advertisement',Boolean(data.ads.length),'Advertisements']] as const;const completed=steps.filter(([,done])=>done).length;const tabs=['Business profile','Storefront','Delivery','Payments','Orders','Notifications','Security & privacy'];
  return <div className="dashboard-content business-settings"><section className="dashboard-card settings-onboarding"><header><div><span>BUSINESS ONBOARDING</span><h2>Complete your store setup</h2><p>{completed} of 10 steps complete</p></div><strong>{Math.round(completed/10*100)}%</strong></header><progress value={completed} max={10}/><div className="settings-steps">{steps.map(([label,done,target],index)=><button className={done?'done':''} onClick={()=>tabs.includes(target as string)&&setTab(target as string)} key={label}>{done?<Check/>:<b>{index+1}</b>}<span>{label}</span></button>)}</div></section><div className="settings-layout"><aside className="settings-tabs">{tabs.map(item=><button className={tab===item?'active':''} onClick={()=>setTab(item)} key={item}>{item}</button>)}</aside><form className="dashboard-card settings-form" onSubmit={save}><header><div><span>PRIVATE BUSINESS SETTINGS</span><h3>{tab}</h3><p>Changes are saved for this business workspace only.</p></div></header>{tab==='Business profile'&&<div className="settings-grid"><label>Store name<input value={settings.storeName} onChange={e=>update('storeName',e.target.value)} required/></label><label>Public phone<input value={settings.publicPhone} onChange={e=>update('publicPhone',e.target.value)} required/></label><label>Public email<input type="email" value={settings.publicEmail} onChange={e=>update('publicEmail',e.target.value)}/></label><label>Trading currency<select value={settings.currency} onChange={e=>update('currency',e.target.value)}><option>USD</option><option>ZWG</option><option>ZAR</option><option>BWP</option></select></label><label>Tax / VAT number<input value={settings.taxNumber} onChange={e=>update('taxNumber',e.target.value)}/></label><label className="wide">Public description<textarea value={settings.description} onChange={e=>update('description',e.target.value)} required/></label></div>}{tab==='Storefront'&&<div className="settings-grid"><label>Logo URL<input value={settings.logo} onChange={e=>update('logo',e.target.value)} placeholder="https://…"/></label><label>Banner URL<input value={settings.banner} onChange={e=>update('banner',e.target.value)} placeholder="https://…"/></label><label className="wide">Opening hours<textarea value={settings.openingHours} onChange={e=>update('openingHours',e.target.value)} placeholder="Mon–Fri 08:00–17:00"/></label><label className="wide">Return policy<textarea value={settings.returnPolicy} onChange={e=>update('returnPolicy',e.target.value)}/></label><div className="settings-preview wide"><Store/><div><b>{settings.storeName||business?.name}</b><p>{settings.description||'Your public store description will appear here.'}</p><small>{settings.openingHours||'Opening hours not configured'}</small></div></div></div>}{tab==='Delivery'&&<div className="settings-grid"><label className="wide">Delivery areas<textarea value={settings.deliveryAreas} onChange={e=>update('deliveryAreas',e.target.value)} placeholder="Harare CBD, Borrowdale, Avondale"/></label><label className="setting-check wide"><input type="checkbox" checked={settings.collectionEnabled} onChange={e=>update('collectionEnabled',e.target.checked)}/><span>Allow customer collection from configured branches</span></label></div>}{tab==='Payments'&&<div className="payment-options">{['Mobile money','Bank card','Bank transfer','Cash on delivery','Cash on collection'].map(method=><label className="setting-check" key={method}><input type="checkbox" checked={settings.paymentMethods.includes(method)} onChange={e=>update('paymentMethods',e.target.checked?[...settings.paymentMethods,method]:settings.paymentMethods.filter(item=>item!==method))}/><span>{method}</span></label>)}</div>}{tab==='Orders'&&<div className="settings-grid"><label className="wide">Default return and fulfilment policy<textarea value={settings.returnPolicy} onChange={e=>update('returnPolicy',e.target.value)} placeholder="Order preparation, cancellation and return rules"/></label></div>}{tab==='Notifications'&&<div className="payment-options"><label className="setting-check"><input type="checkbox" checked={settings.orderNotifications} onChange={e=>update('orderNotifications',e.target.checked)}/><span>New order and fulfilment notifications</span></label><label className="setting-check"><input type="checkbox" checked={settings.lowStockNotifications} onChange={e=>update('lowStockNotifications',e.target.checked)}/><span>Low-stock and inventory alerts</span></label></div>}{tab==='Security & privacy'&&<div className="payment-options"><label className="setting-check"><input type="checkbox" checked={settings.twoFactorEnabled} onChange={e=>update('twoFactorEnabled',e.target.checked)}/><span>Require two-factor authentication for sensitive actions</span></label><p className="privacy-note"><ShieldCheck/> Staff permissions, active sessions, data exports and privacy controls remain protected by backend authorization.</p></div>}<footer><button type="button" onClick={()=>{localStorage.removeItem(key);setSettings({...defaultVendorSettings,storeName:business?.name||''});setMessage('Unsaved local settings reset.')}}>Reset</button><button className="dashboard-primary">Save settings</button></footer>{message&&<div className="customer-feedback">{message}</div>}</form></div></div>;
}

function ProductManager(props: { session: Session; business?: ManagedBusiness; products: Product[]; refresh: () => void }) {
  return <><section className="dashboard-card vendor-capabilities"><header><div><span>PRIVATE CATALOGUE CONTROLS</span><h3>Complete product management</h3></div></header><div className="inventory-summary"><span>Images and descriptions</span><span>Category and brand</span><span>Private cost price</span><span>Specifications and variations</span><span>Warranty information</span><span>Delivery options</span><span>Publish or hide</span><span>Duplicate product</span><span>Restock or advertise</span></div></section><ProductManagerBase {...props}/></>;
}

function ProductManagerBase({ session, business, products, refresh }: { session: Session; business?: ManagedBusiness; products: Product[]; refresh: () => void }) {
  const [open, setOpen] = useState(false); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!business) return; setSaving(true); setError(''); const form = new FormData(event.currentTarget); try { await api.createProduct(session.accessToken, business.id, { name: String(form.get('name')), slug: String(form.get('name')).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''), description: String(form.get('description') || ''), price: Number(form.get('price')), stockQuantity: Number(form.get('stock')), status: 'ACTIVE' }); setOpen(false); refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Product could not be saved'); } finally { setSaving(false); } }
  return <div className="dashboard-content"><div className="dashboard-welcome"><div><span>CATALOG MANAGEMENT</span><h2>Products</h2><p>Add products to {business?.name || 'your store'}; the backend enforces ownership and subscription limits.</p></div><button className="dashboard-primary" onClick={() => setOpen(!open)}>{open ? 'Cancel' : '+ Add product'}</button></div>{open && <form className="management-form" onSubmit={submit}><label>Product name<input name="name" minLength={2} required/></label><label>Price (USD)<input name="price" type="number" min="0" step="0.01" required/></label><label>Opening stock<input name="stock" type="number" min="0" defaultValue="0" required/></label><label className="wide">Description<textarea name="description" rows={3}/></label>{error && <div className="form-error wide">{error}</div>}<button className="dashboard-primary" disabled={saving}>{saving ? 'Saving…' : 'Publish product'}</button></form>}<section className="dashboard-card product-management"><header><div><h3>Product catalogue</h3><p>{products.length} product{products.length === 1 ? '' : 's'} in this business</p></div></header>{products.length ? products.map(product => <div className="data-row" key={product.id}><span className="record-icon"><Package/></span><div><b>{product.name}</b><small>{product.description || 'No description'}</small></div><span className="status-badge">ACTIVE</span><strong>{Number(product.price).toFixed(2)}</strong></div>) : <div className="dashboard-empty"><Package/><h3>No products yet</h3><p>Use “Add product” to publish the first one.</p></div>}</section></div>;
}
